# storage
# =========================
MESSAGE_FILE = "messages.json"

def load_messages():
    if os.path.exists(MESSAGE_FILE):
        try:
            with open(MESSAGE_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except:
            return []
    return []

def save_messages(messages):
    with open(MESSAGE_FILE, "w", encoding="utf-8") as f:
        json.dump(messages, f, indent=2)

